import React from "react";
import { SaveOutlined } from "@ant-design/icons";
import { Affix, Button } from "antd";
import { AppIcon } from "./SVGFiles";

interface Props {
    title: string;
    noSaveBtn?: boolean;
    buttons?: React.ReactNode | React.ReactNode[];
}

export const ConfigHeading: React.FC<Props> = ({ title, noSaveBtn = false, buttons }) => {
    const [isAffixed, setIsAffixed] = React.useState<boolean>(false);

    return (
        <Affix offsetTop={82} onChange={(affix) => setIsAffixed(affix ? affix : false)}>
            <div className={`ss-app-config-heading${isAffixed ? " affixed" : ""}`}>
                <span>
                    <AppIcon asset="tool" width="20" />
                    <span className="m-l-8">{title}</span>
                </span>
                <span>
                    {buttons && buttons}
                    {!noSaveBtn && (
                        <Button icon={<SaveOutlined />} type="link" htmlType="submit">
                            <span className="m-l-8">Save</span>
                        </Button>
                    )}
                </span>
            </div>
        </Affix>
    );
};
